<script setup lang="ts">
import {computed,ref,onMounted,watch} from 'vue'
import {save} from '@tauri-apps/plugin-dialog'
import {command,message,desktop} from '../api'
import {date,localDate,number,counted} from '../format'
import PageHeading from '../components/PageHeading.vue'
import TablePagination from '../components/TablePagination.vue'
interface Filter{templateId:number|null;doctorIds:number[];month?:string;title?:string}
interface Period{from:string;to:string;filters:Filter}
interface CountRow{id?:number;name:string;count:number}
interface Report{summary:{studies:number;patients:number};byType:CountRow[];byDoctor:CountRow[];byMonth:CountRow[]}
interface RecordRow{id:number;patientId:number;patientName:string|null;patientHidden:number;date:string;title:string;doctor:string;conclusionPreview:string}
const to=ref(localDate()),from=ref(localDate().slice(0,4)+'-01-01'),templateId=ref(-1),doctorIds=ref<number[]>([]),busy=ref(false),error=ref(''),success=ref(''),stats=ref<Report>(),applied=ref<Period>(),exporting=ref(false)
const options=ref<{templates:{id:number;name:string;hidden:boolean}[];doctors:{id:number;name:string;hidden:number}[]}>({templates:[],doctors:[]})
const typeItems=computed(()=>[{value:-1,label:'Все виды исследований'},...options.value.templates.map(t=>({value:t.id,label:t.name+(t.hidden?' · Скрыт':'')})),...options.value.templates.some(t=>t.id===0)?[]:[{value:0,label:'Вид не определён'}]])
const doctorItems=computed(()=>[...options.value.doctors.map(d=>({value:d.id,label:d.name+(d.hidden?' · Скрыт':'')})),...options.value.doctors.some(d=>d.id===0)?[]:[{value:0,label:'Врач не указан'}]])
const current=():Period=>({from:from.value,to:to.value,filters:{templateId:templateId.value<0?null:templateId.value,doctorIds:[...doctorIds.value].sort((a,b)=>a-b)}})
const periodChanged=computed(()=>!applied.value||JSON.stringify(current())!==JSON.stringify(applied.value))
let request=0
async function load(){const ticket=++request,period=current();busy.value=true;error.value='';success.value='';stats.value=undefined;applied.value=undefined;try{const [result,refs]=await Promise.all([command<Report>('statistics',period as unknown as Record<string,unknown>),command<typeof options.value>('statistics_options')]);if(ticket===request){stats.value=result;options.value=refs;applied.value=period}}catch(e){if(ticket===request)error.value=message(e)}finally{if(ticket===request)busy.value=false}}
const detailsOpen=ref(false),detailTitle=ref('Исследования отчёта'),detailPeriod=ref<Period>(),detailTotal=ref(0),expectedCount=ref(0),detailItems=ref<RecordRow[]>([]),detailPage=ref(1),detailPageSize=ref(50),detailBusy=ref(false),detailError=ref('')
let detailRequest=0
function showDetails(kind='all',row?:CountRow){if(!applied.value||periodChanged.value||busy.value)return;const period=JSON.parse(JSON.stringify(applied.value)) as Period;if(kind==='byType'&&row){period.filters.templateId=row.id??0;period.filters.title=row.name}else if(kind==='byDoctor'&&row)period.filters.doctorIds=[row.id??0];else if(kind==='byMonth'&&row)period.filters.month=row.name;detailPeriod.value=period;expectedCount.value=row?.count??stats.value?.summary.studies??0;detailTitle.value=row?'Исследования: '+row.name:'Все исследования отчёта';detailPage.value=1;detailsOpen.value=true;loadDetails()}
async function loadDetails(){if(!detailPeriod.value)return;const ticket=++detailRequest;detailBusy.value=true;detailError.value='';try{const result=await command<{total:number;items:RecordRow[]}>('statistics_details',{...detailPeriod.value,page:detailPage.value-1,pageSize:detailPageSize.value});if(ticket===detailRequest){detailTotal.value=result.total;detailItems.value=result.items}}catch(e){if(ticket===detailRequest)detailError.value=message(e)}finally{if(ticket===detailRequest)detailBusy.value=false}}
watch([detailPage,detailPageSize],()=>{if(detailsOpen.value)loadDetails()})
async function exportCsv(details=false){const period=details?detailPeriod.value:applied.value;if(!desktop||!period||exporting.value||busy.value||(!details&&periodChanged.value))return;const snapshot=JSON.parse(JSON.stringify(period)) as Period;exporting.value=true;error.value='';detailError.value='';success.value='';try{const path=await save({defaultPath:`${details?'Исследования':'Статистика'}-${snapshot.from}-${snapshot.to}.csv`,filters:[{name:'CSV',extensions:['csv']}]});if(path){await command(details?'export_statistics_details':'export_statistics',{path,...snapshot});success.value='Отчёт сохранён'}}catch(e){if(details)detailError.value=message(e);else error.value=message(e)}finally{exporting.value=false}}
onMounted(load)
</script>
<template><section class="page-content"><PageHeading title="Статистика" description="Завершённые исследования за выбранный период"><UButton icon="i-lucide-download" variant="outline" :disabled="!desktop||!stats||busy||periodChanged||exporting" :loading="exporting" @click="exportCsv()">Сохранить CSV</UButton></PageHeading><form @submit.prevent="load" class="date-filter"><UFormField label="С"><UInput v-model="from" type="date" required/></UFormField><UFormField label="По"><UInput v-model="to" type="date" required/></UFormField><UFormField label="Вид исследования"><USelect v-model="templateId" :items="typeItems" class="w-64"/></UFormField><UFormField label="Врачи"><USelect v-model="doctorIds" :items="doctorItems" multiple placeholder="Все врачи" class="w-64"/></UFormField><UButton type="submit" :loading="busy">Показать</UButton></form><UAlert v-if="error" color="error" variant="soft" :description="error" class="mb-5"/><UAlert v-if="success" color="success" variant="soft" :description="success" class="mb-5"/><p v-if="stats&&periodChanged" class="text-slate-600 mb-5 no-print">Фильтры изменены. Нажмите «Показать», чтобы обновить отчёт и разрешить выгрузку.</p><template v-if="stats"><p v-if="applied" class="text-slate-600 mb-3">Отчёт за {{date(applied.from)}} — {{date(applied.to)}}</p><div class="flex items-center justify-between flex-wrap gap-4 mb-4"><p class="statistics-summary !mb-0">{{counted(stats.summary.studies,'исследование','исследования','исследований')}} · {{counted(stats.summary.patients,'пациент','пациента','пациентов')}}</p><UButton variant="outline" color="neutral" icon="i-lucide-list" :disabled="busy||periodChanged||!stats.summary.studies" @click="showDetails()">Показать исследования</UButton></div><p class="text-slate-600 mb-7">Черновики, удалённые исследования и записи без пациента не учитываются. Скрытие карточки пациента не исключает завершённые исследования из отчёта. Фильтр врача использует его карточку; подпись в сохранённом документе остаётся прежней.</p><section v-for="(rows,key) in {byType:stats.byType,byDoctor:stats.byDoctor,byMonth:stats.byMonth}" :key="key" class="settings-section"><h2 class="mb-5">{{key==='byType'?'По видам исследований':key==='byDoctor'?'По врачам':'По месяцам'}}</h2><div class="table-scroll"><table class="patient-table"><thead><tr><th>{{key==='byMonth'?'Месяц':'Наименование'}}</th><th class="text-right">Исследований</th></tr></thead><tbody><tr v-for="row in rows" :key="String(row.id)+row.name"><td>{{row.name}}</td><td class="text-right tabular-nums"><UButton variant="link" color="neutral" :disabled="busy||periodChanged" :aria-label="'Показать исследования: '+row.name" @click="showDetails(key,row)">{{number(row.count)}}<UIcon name="i-lucide-arrow-up-right"/></UButton></td></tr><tr v-if="!rows.length"><td colspan="2">За этот период данных нет</td></tr></tbody></table></div></section></template>
<UModal v-model:open="detailsOpen" :title="detailTitle" description="Текущие сохранённые исследования по выбранной строке отчёта" :ui="{content:'sm:max-w-6xl'}"><template #body><UAlert v-if="detailError" color="error" :description="detailError" class="mb-4"/><p v-if="!detailBusy&&detailTotal!==expectedCount" class="mb-4 text-slate-600">Состав данных изменился после построения отчёта: сейчас {{detailTotal}}, в отчёте {{expectedCount}}. Для новых итогов обновите основной отчёт.</p><div class="table-panel"><div class="table-scroll"><table class="patient-table"><thead><tr><th>Дата</th><th>Пациент</th><th>Исследование</th><th>Врач в протоколе</th></tr></thead><tbody><tr v-for="record in detailItems" :key="record.id"><td class="whitespace-nowrap">{{date(record.date)}}<div class="cell-sub">№ {{record.id}}</div></td><td>{{record.patientName||'Без карточки пациента'}}<div v-if="record.patientHidden" class="cell-sub">Карточка скрыта</div></td><td><RouterLink :to="'/studies/'+record.id" class="patient-name">{{record.title}}</RouterLink><p v-if="record.conclusionPreview" class="cell-sub max-w-sm line-clamp-2">{{record.conclusionPreview}}</p></td><td>{{record.doctor}}</td></tr><tr v-if="!detailItems.length&&!detailBusy"><td colspan="4">Исследования не найдены</td></tr></tbody></table></div><TablePagination v-model:page="detailPage" :page-size="detailPageSize" @update:page-size="(size:number)=>{detailPage=1;detailPageSize=size}" :total="detailTotal" :loading="detailBusy"/></div></template><template #footer><UButton color="neutral" variant="outline" @click="detailsOpen=false">Закрыть</UButton><UButton icon="i-lucide-download" :disabled="!desktop||detailBusy||exporting||Boolean(detailError)||!detailTotal" :loading="exporting" @click="exportCsv(true)">Сохранить список CSV</UButton></template></UModal></section></template>
